import openai

class AIAgent:
    def __init__(self):
        self.planner_model = openai.ChatCompletion.create(model="gpt-4", temperature=0.7)
        self.executor_model = openai.ChatCompletion.create(model="claude-3-opus", temperature=0.2)
        self.reviewer_model = openai.ChatCompletion.create(model="gpt-4-turbo", temperature=0.1)

    def process_task(self, task):
        # Step 1: Plan the task
        plan = self.planner_model.create_completion(
            prompt=f"Plan this task: {task}"
        )

        # Step 2: Execute the plan
        result = self.executor_model.create_completion(
            prompt=f"Execute this plan: {plan}"
        )

        # Step 3: Review the result
        review = self.reviewer_model.create_completion(
            prompt=f"Review this result: {result} and suggest improvements"
        )

        return result, review
